const items = $input.all();

for (const item of items) {
  const idActivo = item.json.id_activo;
  const idVersion = item.json.id_version;
  const numeroVersion = item.json.numero_version;
  const fileName = item.json.ruta_objeto;

  const paquete = {
    meta: {
      sistema: "CommunityLab",
      id_activo: idActivo,
      id_version: idVersion,
      numero_version: numeroVersion,
      generado_en: new Date().toISOString()
    },
    contenido: item.json.contenido
  };

  const contenidoJson = JSON.stringify(paquete, null, 2);
  const buffer = Buffer.from(contenidoJson, "utf8");

  item.json.nombre_archivo = fileName;
  item.json.tamano_bytes = buffer.length;
  item.binary = {
    data: await this.helpers.prepareBinaryData(
      buffer,
      fileName.split("/").pop(),
      "application/json"
    )
  };
}

return items;
